.graceart-care li { font-size: 14px; line-height: 1.6; color: var(--wp--preset--color--body-text); margin: 0 0 6px; }

/* Omrvinky Yoast */
.graceart-cat-header .yoast-breadcrumbs, .graceart-page-header .yoast-breadcrumbs { font-size: 14px; color: var(--wp--preset--color--muted); }
.graceart-product .yoast-breadcrumbs { font-size: 13px; color: var(--wp--preset--color--muted); }
.graceart-page-header .yoast-breadcrumbs a, .graceart-product .yoast-breadcrumbs a { color: var(--wp--preset--color--muted); text-decoration: none; }
.yoast-breadcrumbs a:hover { text-decoration: underline; }
.yoast-breadcrumbs .breadcrumb_last { overflow-wrap: anywhere; }

/* Stránka produktu na úzkom mobile: − 1 + a srdiečko v 1. rade, Pridať do košíka na celú šírku v 2. rade */
@media (max-width: 480px) {
  .graceart-product-form .quantity { order: 1; }
  .graceart-product-form .graceart-wishlist { order: 2; }
  .graceart-product-form .single_add_to_cart_button { order: 3; flex: 1 1 100% !important; width: 100% !important; min-width: 0; padding: 0 20px !important; }
}

/* Okienko Pridané do košíka (functions.php: graceart_pridane_html, assets/js/pridane.js) */
dialog.graceart-pridane { width: min(580px, calc(100% - 32px)); max-width: none; max-height: calc(100% - 32px); padding: 0; border: 1px solid var(--wp--preset--color--line); border-radius: 4px; background: var(--wp--preset--color--base); color: var(--wp--preset--color--body-text); box-shadow: 0 18px 50px rgba(59, 46, 37, 0.18); }
dialog.graceart-pridane:not([open]) { display: none; }
dialog.graceart-pridane::backdrop { background: rgba(59, 46, 37, 0.45); }
.graceart-pridane-obsah { padding: 32px 36px; }
.graceart-pridane-hlava { display: flex; align-items: center; justify-content: space-between; gap: 12px; margin-bottom: 24px; }
.graceart-pridane-nadpis { margin: 0; display: flex; align-items: center; gap: 12px; font-family: var(--wp--preset--font-family--jost); font-size: 15px; font-weight: 500; letter-spacing: 0.06em; text-transform: uppercase; color: var(--wp--preset--color--ink); }
.graceart-pridane-fajka { position: relative; flex: none; width: 24px; height: 24px; border-radius: 50%; background: #4ab866; }
.graceart-pridane-fajka::after { content: ""; position: absolute; left: 9px; top: 5px; width: 6px; height: 11px; border: solid #fff; border-width: 0 2px 2px 0; transform: rotate(45deg); }
.graceart-pridane-zavriet { width: 40px; height: 40px; padding: 0; border: 0; background: none; font-size: 32px; line-height: 1; color: var(--wp--preset--color--muted); cursor: pointer; }
.graceart-pridane-zavriet:hover { color: var(--wp--preset--color--ink); }
.graceart-pridane-produkt { display: flex; gap: 22px; align-items: flex-start; padding-bottom: 24px; border-bottom: 1px solid var(--wp--preset--color--line); }
.graceart-pridane-produkt img { flex: none; width: 130px; height: 130px; object-fit: cover; border-radius: 2px; background: var(--wp--preset--color--cream); }
.graceart-pridane-produkt p { margin: 0; }
.graceart-pridane-meno { margin-bottom: 6px !important; font-size: 18px; font-weight: 500; line-height: 1.35; color: var(--wp--preset--color--ink); }
.graceart-pridane-detail { font-size: 14px; line-height: 1.5; color: var(--wp--preset--color--muted); }
.graceart-pridane-cena { margin-top: 10px !important; font-size: 18px; color: var(--wp--preset--color--ink); }
.graceart-pridane-kosik { margin: 20px 0 26px; font-size: 15px; line-height: 1.5; }
.graceart-pridane-kosik strong { font-weight: 500; color: var(--wp--preset--color--ink); }
.graceart-pridane-tlacidla { display: flex; gap: 12px; }
.graceart-pridane-tlacidla > * { flex: 1 1 0; display: flex; align-items: center; justify-content: center; box-sizing: border-box; height: 48px; padding: 0 20px; border-radius: 999px; font-family: var(--wp--preset--font-family--jost); font-size: 13px; font-weight: 400; letter-spacing: 0.06em; text-transform: uppercase; text-decoration: none; white-space: nowrap; cursor: pointer; }
.graceart-pridane-pokracovat { border: 1px solid var(--wp--preset--color--brown); background: transparent; color: var(--wp--preset--color--brown); }
.graceart-pridane-pokracovat:hover { background: var(--wp--preset--color--cream); }
.graceart-pridane-do-kosika { border: 1px solid #A67A5B; background: #A67A5B; color: #fff !important; }
.graceart-pridane-do-kosika:hover { border-color: var(--wp--preset--color--brown); background: var(--wp--preset--color--brown); }
/* odkaz WooCommerce „Zobraziť košík“ za tlačidlom v zozname nahrádza okienko */
.woocommerce ul.products li.product a.added_to_cart { display: none !important; }
@media (max-width: 480px) {
  .graceart-pridane-obsah { padding: 24px 20px; }
  .graceart-pridane-produkt { gap: 16px; }
  .graceart-pridane-produkt img { width: 96px; height: 96px; }
  .graceart-pridane-meno { font-size: 16px; }
  .graceart-pridane-cena { font-size: 16px; }
  .graceart-pridane-tlacidla { flex-direction: column-reverse; }
}
/* Odpovede na hodnotenia */
.graceart-reviews .wp-block-woocommerce-product-review-template > li { display: flex; flex-direction: column; }
.graceart-reviews .wp-block-woocommerce-product-review-template > li > .graceart-review-card { flex: 1 0 auto; }
.graceart-reviews .wp-block-woocommerce-product-review-template li ol { margin: 8px 0 0 20px; }
.graceart-reviews li ol .graceart-review-card { background: var(--wp--preset--color--cream); border-color: var(--wp--preset--color--cream); padding: 20px 24px; }
.graceart-reviews li ol .wp-block-woocommerce-product-review-rating:not(:has(.wc-block-product-review-rating__stars)) { display: none; }
.graceart-reviews li ol .wp-block-woocommerce-product-review-content { margin-top: 0 !important; }
.graceart-reviews li ol .graceart-review-meta { margin-top: 10px !important; }
@media (max-width: 600px) { .graceart-reviews .wp-block-woocommerce-product-review-template li ol { margin-left: 12px; } .graceart-reviews li ol .graceart-review-card { padding: 16px 18px; } }
/* Karty produktov: cena a tlačidlo vždy dole v jednej línii (aj pri dlhom názve) */
.woocommerce ul.products li.product .woocommerce-loop-product__link { flex: 1 0 auto; display: flex !important; flex-direction: column; }
.woocommerce ul.products li.product .woocommerce-loop-product__link .price { margin-top: auto !important; }
@media (max-width: 768px) { .woocommerce ul.products li.product .woocommerce-loop-product__title { min-height: 2.8em; } }
